using System;
using System.Collections.Generic;
using System.Globalization;
using System.Linq;
using System.Text;
using System.Text.Json;
using Autodesk.AutoCAD.ApplicationServices;
using Autodesk.AutoCAD.Runtime;
using AcadApp = Autodesk.AutoCAD.ApplicationServices.Application;
using Exception = System.Exception;
using WinForms = System.Windows.Forms;

namespace PipingSpecPlugin.Tracing
{
    /// <summary>
    /// PSTRACING — heat tracing ("спутники") of the pipe lines, generated by an algorithm (no AI involved).
    ///
    /// A dialog lists the lines of the drawing; the user ticks the lines to trace. For every line the
    /// generator walks the whole route (straight runs, 90° elbows, risers, flanges, valves, spectacle
    /// blinds, tees), puts two DN20 25x4 tracers on the sides of the pipe below its axis (view 3 of the
    /// user's sample: ±45° from the vertical), steps them round the wide parts, heats vertical and
    /// horizontal branches (vents, drains), closes the loop with 180° bends beyond the free ends and
    /// checks every part against the main pipes. Everything is built from Plant 3D parts (the tracer
    /// pipe of the chosen spec, "ИЗГИБ ТРУБЫ" bends, Buttweld connectors made by Plant 3D's own
    /// ConnectorWrapper), so the tracing is a normal part of the model.
    ///
    /// The plan of all chosen lines is computed first without touching the drawing and shown with its
    /// warnings (what could not be heated, tight places); the parts are created only after the
    /// confirmation, on the layer «Спутник» (red, colour ByLayer). Where a collision with the main line
    /// cannot be avoided the part is created all the same, a warning says so and the parts concerned go
    /// to the layer «Спутник-коллизия» (violet).
    /// </summary>
    public class TracingCommand
    {
        static readonly TracingParameters Par = new TracingParameters();
        const string LayerName = "Спутник";
        const int LayerColorIndex = 1;                 // red
        const string CollisionLayerName = "Спутник-коллизия";
        const int CollisionColorIndex = 200;           // violet

        sealed class Route
        {
            public TracingLine Line; public string Start; public JsonElement Plan;
            public int Pipes, Bends, Closing, Welds, Hits; public double MinClear;
            public List<string> Warnings = new List<string>();
        }

        [CommandMethod("PSTRACING")]
        public void Run()
        {
            var doc = AcadApp.DocumentManager.MdiActiveDocument;
            if (doc == null) return;
            var ed = doc.Editor;
            try
            {
                var lines = TracingEngine.CollectLines(doc);
                if (lines.Count == 0)
                {
                    WinForms.MessageBox.Show("В активном чертеже нет труб Plant 3D с номером линии.", "Спутник", WinForms.MessageBoxButtons.OK, WinForms.MessageBoxIcon.Information);
                    return;
                }

                // 1. the lines
                List<TracingLine> chosen;
                using (var dlg = new TracingLinesDialog(lines, Par, TracingEngine.SpecNames()))
                {
                    if (dlg.ShowDialog() != WinForms.DialogResult.OK) return;
                    chosen = dlg.Selected;
                }
                if (chosen.Count == 0) return;

                // 2. the plan of every chosen line: nothing in the drawing changes
                ed.WriteMessage("\nРасчёт спутника (чертёж не меняется)...");
                var routes = new List<Route>(); var notes = new List<string>();
                foreach (var line in chosen) PlanLine(line, routes, notes);
                var report = PlanReport(chosen, routes, notes);
                if (routes.Count == 0)
                {
                    using (var rd = new TracingReportDialog("Спутник: расчёт", report, "Закрыть", false)) rd.ShowDialog();
                    return;
                }
                using (var rd = new TracingReportDialog("Спутник: расчёт (чертёж пока не изменён)", report, "Создать спутник", true))
                    if (rd.ShowDialog() != WinForms.DialogResult.OK) { ed.WriteMessage("\nОтменено, чертёж не изменён."); return; }

                if (IsDirty())
                {
                    var answer = WinForms.MessageBox.Show(
                        "В чертеже есть несохранённые изменения.\n\nСоздание спутника идёт через внутренние механизмы Plant 3D; "
                      + "при редком сбое Plant 3D может закрыться аварийно. Рекомендуется сохранить чертёж заранее.\n\n"
                      + "Создать спутник без сохранения?",
                        "Спутник", WinForms.MessageBoxButtons.YesNo, WinForms.MessageBoxIcon.Question);
                    if (answer != WinForms.DialogResult.Yes) { ed.WriteMessage("\nОтменено: сохраните чертёж и запустите команду снова."); return; }
                }

                // 3. creation (its own rollback removes everything of a route again when any check fails)
                var result = new StringBuilder(); int made = 0, failed = 0, hitParts = 0; bool stopped = false;
                for (int ri = 0; ri < routes.Count; ri++)
                {
                    var r = routes[ri];
                    ed.WriteMessage($"\nСоздание спутника: линия {r.Line.Tag}...");
                    JsonElement created;
                    try
                    {
                        created = Call(r.Start, dry: false).GetProperty("created");
                    }
                    catch (Exception ex)
                    {
                        failed++;
                        result.AppendLine($"{r.Line.Tag}: НЕ создано — {ex.Message}");
                        // after an erase of a failed tracing Plant 3D is not safe for the next big creation (it crashed that way): stop here
                        if (ex.Message.Contains("rolled back") && ri + 1 < routes.Count)
                        {
                            result.AppendLine("Остальные маршруты не создавались: после отката Plant 3D лучше перезапустить (без сохранения) и повторить.");
                            stopped = true;
                        }
                        if (stopped) break;
                        continue;
                    }
                    // the parts exist from here on: a failure of the layer must not be reported as "not created"
                    var all = created.GetProperty("handles").EnumerateArray().Select(h => h.GetString()).ToList();
                    var hits = new HashSet<string>(created.GetProperty("collision_handles").EnumerateArray().Select(h => h.GetString()));
                    made++; hitParts += hits.Count;
                    string layerNote = "";
                    try
                    {
                        MoveToLayer(all.Where(h => !hits.Contains(h)).ToList(), LayerName, LayerColorIndex);
                        MoveToLayer(all.Where(h => hits.Contains(h)).ToList(), CollisionLayerName, CollisionColorIndex);
                    }
                    catch (Exception ex) { layerNote = $" ВНИМАНИЕ: детали созданы, но слой не назначен ({ex.Message}); не запускайте создание повторно, перенесите детали на слой вручную."; }
                    result.AppendLine($"{r.Line.Tag}: создано — труб {Get(created, "pipes")}, изгибов {Get(created, "bends")}, замыкающих изгибов {Get(created, "closing_bends")}, стыков {Get(created, "welds")}"
                                    + (hits.Count > 0 ? $"; фиолетовых деталей (коллизия): {hits.Count}" : "") + "." + layerNote);
                }
                result.AppendLine();
                result.AppendLine($"Слой «{LayerName}» — красный, цвет «по слою». Слой «{CollisionLayerName}» — фиолетовый: детали в местах, где столкновение с основной линией неизбежно.");
                result.AppendLine("Проверьте результат и сохраните чертёж.");
                ed.WriteMessage($"\nСпутник: создано маршрутов {made}, с ошибкой {failed}" + (hitParts > 0 ? $", деталей в коллизии (фиолетовые): {hitParts}." : "."));
                using (var rd = new TracingReportDialog("Спутник: результат", result.ToString(), "Закрыть", false)) rd.ShowDialog();
            }
            catch (Exception ex)
            {
                ed.WriteMessage("\nСпутник не создан: " + ex.Message);
                WinForms.MessageBox.Show(ex.Message, "Спутник не создан", WinForms.MessageBoxButtons.OK, WinForms.MessageBoxIcon.Warning);
            }
        }

        // The routes of a line: the longest free pipe first; every route that works marks its pipes as done; a line may consist of several separate routes.
        static void PlanLine(TracingLine line, List<Route> routes, List<string> notes)
        {
            var covered = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            int found = 0, attempts = 0; var errors = new List<string>();
            foreach (var p in line.Pipes.OrderByDescending(q => q.length))
            {
                if (covered.Contains(p.handle)) continue;
                if (found > 0 && p.length < 300) break;              // short stubs left over (vent branches etc.) are not routes of their own
                if (found == 0 && attempts >= 8) break;              // the same failure again and again: not worth more attempts
                attempts++;
                try
                {
                    var res = Call(p.handle, dry: true);
                    var plan = res.GetProperty("plan");
                    foreach (var s in plan.GetProperty("route").EnumerateArray())
                    {
                        var t = s.GetString() ?? ""; int sp = t.IndexOf(' ');
                        if (sp > 0) covered.Add(t.Substring(sp + 1));
                    }
                    var parts = plan.GetProperty("parts");
                    var cc = plan.GetProperty("collision_check");
                    var r = new Route
                    {
                        Line = line, Start = p.handle, Plan = plan,
                        Pipes = GetInt(parts, "pipes"), Bends = GetInt(parts, "bends"), Closing = GetInt(parts, "closing_bends_180"), Welds = GetInt(parts, "welds"),
                        Hits = cc.TryGetProperty("parts_in_collision", out var hp) ? hp.GetInt32() : 0,
                        MinClear = cc.GetProperty("min_clearance_mm").GetDouble(),
                    };
                    foreach (var w in plan.GetProperty("warnings").EnumerateArray())
                    {
                        var t = w.GetString() ?? "";
                        if (t.StartsWith("Riser branch", StringComparison.Ordinal) || t.StartsWith("Lateral offsets", StringComparison.Ordinal)
                            || t.StartsWith("The closing bends lie", StringComparison.Ordinal) || t.StartsWith("COLLISIONS with the route", StringComparison.Ordinal)) continue;
                        r.Warnings.Add(t);
                    }
                    routes.Add(r); found++;
                }
                catch (Exception ex)
                {
                    covered.Add(p.handle);
                    if (!errors.Contains(ex.Message)) errors.Add(ex.Message);
                    if (found > 0 && p.length >= 300) notes.Add($"{line.Tag}: маршрут от трубы {p.handle} ({p.length:0} мм) не рассчитан — {ex.Message}");
                }
            }
            if (found == 0) notes.Add($"{line.Tag}: спутник рассчитать не удалось — {(errors.Count > 0 ? string.Join(" | ", errors) : "в линии нет подходящих труб")}");
        }

        static string PlanReport(List<TracingLine> chosen, List<Route> routes, List<string> notes)
        {
            var sb = new StringBuilder();
            sb.AppendLine($"Линий выбрано: {chosen.Count}, маршрутов рассчитано: {routes.Count}.");
            sb.AppendLine();
            foreach (var r in routes)
            {
                sb.AppendLine($"Линия {r.Line.Tag} (DN {r.Line.Sizes}), маршрут от трубы {r.Start}:");
                sb.AppendLine($"  будет создано: труб {r.Pipes}, изгибов {r.Bends}, замыкающих изгибов 180° {r.Closing}, сварных стыков {r.Welds};");
                sb.AppendLine($"  минимальный зазор до основной трубы: {r.MinClear.ToString("0.##", CultureInfo.CurrentCulture)} мм"
                            + (r.Hits > 0 ? $"; деталей в неизбежной коллизии (будут фиолетовыми): {r.Hits}" : "") + ".");
                foreach (var w in r.Warnings) sb.AppendLine("  ! " + (w.Length > 240 ? w.Substring(0, 240) + "…" : w));
                sb.AppendLine();
            }
            foreach (var n in notes) sb.AppendLine("! " + n);
            return sb.ToString();
        }

        static JsonElement Call(string handle, bool dry)
        {
            var args = JsonSerializer.SerializeToElement(new Dictionary<string, object>
            {
                ["pipe"] = handle,
                ["spec"] = Par.Spec, ["nd"] = Par.Nd, ["wall"] = Par.Wall, ["gap"] = Par.Gap, ["radius"] = Par.Radius,
                ["min_gap"] = Par.MinGap,
                ["dry_run"] = dry,
            });
            return JsonSerializer.SerializeToElement(TracingEngine.CreateTracingRoute(args));
        }

        // The parts go to their layer in small batches (Plant 3D is more stable with small ones).
        static void MoveToLayer(List<string> handles, string layer, int color)
        {
            for (int i = 0; i < handles.Count; i += 12)
            {
                var args = JsonSerializer.SerializeToElement(new Dictionary<string, object>
                {
                    ["layer"] = layer, ["color"] = color, ["handles"] = handles.Skip(i).Take(12).ToList(),
                });
                TracingEngine.SetLayer(args);
            }
        }

        static bool IsDirty()
        {
            try { return Convert.ToInt32(AcadApp.GetSystemVariable("DBMOD")) != 0; }
            catch { return false; }
        }

        static int GetInt(JsonElement e, string name) => e.TryGetProperty(name, out var v) && v.ValueKind == JsonValueKind.Number ? v.GetInt32() : 0;

        static string Get(JsonElement e, string name)
            => e.TryGetProperty(name, out var v) ? (v.ValueKind == JsonValueKind.Number ? v.GetInt32().ToString(CultureInfo.InvariantCulture) : v.ToString()) : "?";
    }
}
